import glob
import unittest

# Load the RobotPet class from the exercise file printed in the book.
for path in sorted(glob.glob("*.py")):
    source = open(path).read()
    if "class RobotPet" in source and "unittest" not in source:
        exec(compile(source, path, "exec"))
        break


class TestRobotPet(unittest.TestCase):
    def test_name_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.name, "Bolt")

    def test_battery_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.battery, 100)

    def test_mood_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.mood, "happy")

    def test_show_talent(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.show_talent(), "performs a generic trick!")


if __name__ == "__main__":
    unittest.main(verbosity=2)
